    @Test
    void anUnknownReservationIsNotFound() {
        assertEquals(ErrorCode.RESERVATION_NOT_FOUND, errorOf(() -> service.find(42)));
    }

    @Test
    void corporatePlanRequiresValidCompanyCode() {
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(
                () -> service.create(new NewReservation(
                        101, new Guest("Ana", "ana@example.com", "123.456.789-09"),
                        LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 2, RatePlan.CORPORATE, null))));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(
                () -> service.create(new NewReservation(
                        101, new Guest("Ana", "ana@example.com", "123.456.789-09"),
                        LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 2, RatePlan.CORPORATE, "INVALID"))));

        // Valid codes should work
        Reservation tecnosul = service.create(new NewReservation(
                101, new Guest("Ana", "ana@example.com", "123.456.789-09"),
                LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 2, RatePlan.CORPORATE, "TECNOSUL"));
        assertEquals(new BigDecimal("686.22"), tecnosul.price().total());

        Reservation agrovale = service.create(new NewReservation(
                102, new Guest("Ana", "ana@example.com", "123.456.789-09"),
                LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 2, RatePlan.CORPORATE, "AGROVALE"));
        assertEquals(new BigDecimal("639.44"), agrovale.price().total());
    }

    @Test
    void corporatePlanFullRefundOnCancellation() {
        Reservation reservation = service.create(new NewReservation(
                101, new Guest("Ana", "ana@example.com", "123.456.789-09"),
                LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 2, RatePlan.CORPORATE, "TECNOSUL"));
        service.confirm(reservation.id());

        BigDecimal refund = service.cancel(reservation.id()).refund();
        assertEquals(reservation.price().total(), refund);
    }

    @Test
    void weekendPackageRequiresFridayToSunday() {
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(
                () -> service.create(new NewReservation(
                        101, new Guest("Ana", "ana@example.com", "123.456.789-09"),
                        LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 2, RatePlan.WEEKEND_PACKAGE, null))));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(
                () -> service.create(new NewReservation(
                        101, new Guest("Ana", "ana@example.com", "123.456.789-09"),
                        LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 15), 2, RatePlan.WEEKEND_PACKAGE, null))));

        // 12/03/2027 is Friday, 14/03/2027 is Sunday, valid weekend package
        Reservation weekend = service.create(new NewReservation(
                101, new Guest("Ana", "ana@example.com", "123.456.789-09"),
                LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 14), 2, RatePlan.WEEKEND_PACKAGE, null));
        assertEquals(new BigDecimal("520.00"), weekend.price().total());
    }

    @Test
    void weekendPackageHalfRefundOnCancellation() {
        Reservation weekend = service.create(new NewReservation(
                101, new Guest("Ana", "ana@example.com", "123.456.789-09"),
                LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 14), 2, RatePlan.WEEKEND_PACKAGE, null));
        service.confirm(weekend.id());

        BigDecimal refund = service.cancel(weekend.id()).refund();
        assertEquals(new BigDecimal("260.00"), refund);
    }

    @Test
    void longStayRequires7Nights() {
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(
                () -> service.create(new NewReservation(
                        101, new Guest("Ana", "ana@example.com", "123.456.789-09"),
                        LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 16), 2, RatePlan.LONG_STAY, null))));

        // 7 nights should work
        Reservation longStay = service.create(new NewReservation(
                101, new Guest("Ana", "ana@example.com", "123.456.789-09"),
                LocalDate.of(2027, 3, 1), LocalDate.of(2027, 3, 8), 2, RatePlan.LONG_STAY, null));
